import * as THREE from 'three';
import {GLTFLoader} from 'three/addons/loaders/GLTFLoader.js';
export function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
export async function readImage(file){if(!file||!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Choose PNG, JPEG, or WebP.');if(file.size>8*1024*1024)throw Error('Image limit is 8 MB.');return new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=()=>no(Error('Image read failed.'));r.readAsDataURL(file);});}
export function imageElement(data){return new Promise((ok,no)=>{const im=new Image();im.onload=()=>ok(im);im.onerror=()=>no(Error('Image decode failed.'));im.src=data;});}
export async function cropImage(data,crop){const im=await imageElement(data);const {x,y,w,h}=crop;if([x,y,w,h].some(v=>!Number.isFinite(v))||x<0||y<0||w<=0||h<=0||x+w>100||y+h>100)throw Error('Crop must stay within 0–100% of the photograph.');const sw=im.width*w/100,sh=im.height*h/100,scale=Math.min(1,2048/Math.max(sw,sh)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(sw*scale));c.height=Math.max(1,Math.round(sh*scale));const ctx=c.getContext('2d');ctx.drawImage(im,im.width*x/100,im.height*y/100,sw,sh,0,0,c.width,c.height);if(crop.mask){const pixels=ctx.getImageData(0,0,c.width,c.height),d=pixels.data,t=Math.max(0,Math.min(100,crop.tolerance));for(let i=0;i<d.length;i+=4){const delta=Math.max(255-d[i],255-d[i+1],255-d[i+2]);if(delta<=t)d[i+3]=0;}ctx.putImageData(pixels,0,0);}return c.toDataURL('image/png');}
export async function readModel(file){if(!/\.(glb|gltf)$/i.test(file.name)||file.size>20*1024*1024)throw Error('Choose GLB or self-contained GLTF, up to 20 MB.');const data=await file.arrayBuffer();let json;if(/\.gltf$/i.test(file.name)){json=JSON.parse(new TextDecoder().decode(data));}else{const dv=new DataView(data);if(dv.getUint32(0,true)!==0x46546c67)throw Error('Invalid GLB file.');for(let pos=12;pos+8<=data.byteLength;){const len=dv.getUint32(pos,true),type=dv.getUint32(pos+4,true);if(type===0x4e4f534a){json=JSON.parse(new TextDecoder().decode(data.slice(pos+8,pos+8+len)));break;}pos+=8+len;}}
 if(!json||json.asset?.version!=='2.0')throw Error('A valid glTF 2.0 asset is required.');for(const v of [...(json.buffers||[]),...(json.images||[])])if(v.uri&&!v.uri.startsWith('data:'))throw Error('External model resources are unsupported. Embed textures and buffers in GLB/GLTF.');if(json.extensionsRequired?.some(x=>['KHR_draco_mesh_compression','EXT_meshopt_compression','KHR_texture_basisu'].includes(x)))throw Error('Upload an uncompressed GLB/GLTF; compressed extensions are unsupported.');return new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=no;r.readAsDataURL(file);});}
export function disposeTree(root){const geometries=new Set(),materials=new Set(),textures=new Set();root?.traverse(o=>{if(o.geometry)geometries.add(o.geometry);(Array.isArray(o.material)?o.material:[o.material]).filter(Boolean).forEach(m=>materials.add(m));});materials.forEach(m=>{Object.values(m).forEach(t=>{if(t?.isTexture)textures.add(t);});m.dispose();});geometries.forEach(g=>g.dispose());textures.forEach(t=>t.dispose());}
export class AssetCache{
 constructor(renderer){this.renderer=renderer;this.images=new Map();this.models=new Map();this.photos=new Map();}
 async image(data){if(!data)return null;if(!this.images.has(data)){this.images.set(data,new THREE.TextureLoader().loadAsync(data).then(t=>{t.colorSpace=THREE.SRGBColorSpace;t.anisotropy=this.renderer.capabilities.getMaxAnisotropy();return t;}).catch(e=>{this.images.delete(data);throw e;}));}return this.images.get(data);}
 async photo(data){if(!data)return null;if(!this.photos.has(data))this.photos.set(data,(async()=>{const original=await this.image(data),im=original.image,c=document.createElement('canvas');c.width=im.width;c.height=im.height;const ctx=c.getContext('2d');ctx.drawImage(im,0,0);const d=ctx.getImageData(0,0,c.width,c.height).data;let minX=c.width,minY=c.height,maxX=-1,maxY=-1;for(let y=0;y<c.height;y++)for(let x=0;x<c.width;x++)if(d[(y*c.width+x)*4+3]>12){minX=Math.min(minX,x);maxX=Math.max(maxX,x);minY=Math.min(minY,y);maxY=Math.max(maxY,y);}if(maxX<0)throw Error('The photograph is fully transparent after masking.');if(minX===0&&minY===0&&maxX===c.width-1&&maxY===c.height-1)return original;const crop=document.createElement('canvas');crop.width=maxX-minX+1;crop.height=maxY-minY+1;crop.getContext('2d').drawImage(c,minX,minY,crop.width,crop.height,0,0,crop.width,crop.height);const t=new THREE.CanvasTexture(crop);t.colorSpace=THREE.SRGBColorSpace;t.anisotropy=original.anisotropy;return t;})().catch(e=>{this.photos.delete(data);throw e;}));return this.photos.get(data);}
 async model(data){if(!data)return null;if(!this.models.has(data)){this.models.set(data,(async()=>{const a=await fetch(data).then(r=>r.arrayBuffer());validateModelBytes(a);const loader=new GLTFLoader();const obj=await loader.parseAsync(a,'');return obj.scene;})().catch(e=>{this.models.delete(data);throw e;}));}return this.models.get(data);}
 async prepare(catalog,branding){await Promise.all([...catalog.filter(p=>p.art).map(p=>this.image(p.art)),...catalog.filter(p=>p.model).map(p=>this.model(p.model)),...Object.values(branding).filter(Boolean).map(x=>this.image(x))]);}
 prune(catalog,branding){const images=new Set([...catalog.map(p=>p.art),...Object.values(branding)]),models=new Set(catalog.map(p=>p.model));for(const [data,p] of this.photos)if(!images.has(data)){p.then(t=>t.dispose()).catch(()=>{});this.photos.delete(data);}for(const [data,p] of this.images)if(!images.has(data)){p.then(t=>t.dispose()).catch(()=>{});this.images.delete(data);}for(const [data,p] of this.models)if(!models.has(data)){p.then(disposeTree).catch(()=>{});this.models.delete(data);}}
}
let database;
async function db(){if(!database)database=new Promise((ok,no)=>{const r=indexedDB.open('display-studio-phase2',1);r.onupgradeneeded=()=>r.result.createObjectStore('projects');r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error);});return database;}
export async function persist(project){const d=await db();return new Promise((ok,no)=>{const t=d.transaction('projects','readwrite');t.objectStore('projects').put(project,'current');t.oncomplete=ok;t.onerror=()=>no(t.error);});}
export async function restore(){const d=await db();return new Promise((ok,no)=>{const r=d.transaction('projects').objectStore('projects').get('current');r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error);});}

function validateModelBytes(data){if(data.byteLength>20*1024*1024)throw Error('Model exceeds 20 MB.');let json;const dv=new DataView(data);if(data.byteLength>=12&&dv.getUint32(0,true)===0x46546c67){for(let pos=12;pos+8<=data.byteLength;){const len=dv.getUint32(pos,true),type=dv.getUint32(pos+4,true);if(type===0x4e4f534a){json=JSON.parse(new TextDecoder().decode(data.slice(pos+8,pos+8+len)));break;}pos+=8+len;}}else json=JSON.parse(new TextDecoder().decode(data));if(json?.asset?.version!=='2.0')throw Error('Invalid glTF 2.0 model.');for(const x of [...(json.buffers||[]),...(json.images||[])])if(x.uri&&!x.uri.startsWith('data:'))throw Error('Embed all model resources; external resources are unsupported.');if(json.extensionsRequired?.some(x=>['KHR_draco_mesh_compression','EXT_meshopt_compression','KHR_texture_basisu'].includes(x)))throw Error('Compressed model extensions are unsupported.');}

export async function backupProject(project){const d=await db();return new Promise((ok,no)=>{const t=d.transaction('projects','readwrite');t.objectStore('projects').put(project,'before-reference-preview');t.oncomplete=ok;t.onerror=()=>no(t.error);});}
export async function previousProject(){const d=await db();return new Promise((ok,no)=>{const r=d.transaction('projects').objectStore('projects').get('before-reference-preview');r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error);});}
